def triangle_kind(a,b,c):
    x,y,z=sorted([a,b,c])
    return "INVALID" if x+y<z else "RIGHT" if x*x+y*y==z*z else "ACUTE"

def is_prime(n):
    d=2
    while d*d<n:
        if n%d==0:return False
        d+=1
    return n>=2

def second_largest(values):
    a=sorted(set(values))
    return a[1] if len(a)>1 else None

def median(values):
    a=sorted(values);i=len(a)//2
    return a[i] if len(a)%2 else (a[i-1]+a[i])//2

def word_counts(text):
    d={}
    for x in text.split(): d[x]=d.get(x,0)+1
    return d

def group_totals(records):
    d={}
    for k,v in records:
        if v>0:d[k]=d.get(k,0)+v
    return d

def gcd_nonnegative(a,b):
    while b:a,b=b,a%b
    return a

